using System;using System.IO;using System.Threading.Tasks;using System.Windows;using System.Windows.Media;using System.Windows.Media.Imaging;using CodexStrip;
class ScreenSimulation {
 static void Save(BitmapSource b,string path){var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}
 [STAThread]static void Main(){Directory.CreateDirectory("outputs/ScreenSimulation");Settings.DataDir=Path.GetFullPath("work/simulation-data");var app=new Application();var w=new StripWindow(true){Width=1920,Height=480,Left=0,Top=0};w.Config.Count=4;w.Config.Host="all";w.Loaded+=async delegate{try{w.SetTheme("light");double[] scales={1,1.5,2,1.5};for(int i=0;i<4;i++){bool portrait=i==3;double scale=scales[i];w.Width=(portrait?480:1920)/scale;w.Height=(portrait?1920:480)/scale;await Task.Delay(400);w.UpdateLayout();var b=new RenderTargetBitmap(portrait?480:1920,portrait?1920:480,96*scale,96*scale,PixelFormats.Pbgra32);b.Render(w);Save(b,"outputs/ScreenSimulation/"+(portrait?"portrait-150":("landscape-"+(int)(scale*100)))+".png");}
 var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawRectangle(Brushes.White,null,new Rect(0,0,1040,1030));string[] captions={"100% · 1920 × 480 logical pixels","150% · 1280 × 320 logical pixels","200% · 960 × 240 logical pixels"};for(int i=0;i<3;i++){double y=20+i*326;dc.DrawText(new FormattedText(captions[i],System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),22,Brushes.Black),new Point(40,y));var b=new BitmapImage(new Uri(Path.GetFullPath("outputs/ScreenSimulation/landscape-"+new[]{100,150,200}[i]+".png")));dc.DrawImage(b,new Rect(40,y+44,960,240));}dc.DrawText(new FormattedText("DEMO DATA · Same physical screen · Scaled comparison, not life-size",System.Globalization.CultureInfo.InvariantCulture,FlowDirection.LeftToRight,new Typeface("Segoe UI"),16,Brushes.DimGray),new Point(40,1000));}var sheet=new RenderTargetBitmap(1040,1030,96,96,PixelFormats.Pbgra32);sheet.Render(visual);Save(sheet,"outputs/ScreenSimulation/comparison.png");File.WriteAllText("work/screen-simulation.txt","PASS: three 1920x480 physical rasters at 100/150/200%; 480x1920 portrait at 150%; demo-only config");}catch(Exception e){File.WriteAllText("work/screen-simulation.txt",e.ToString());}finally{w.Close();}};app.Run(w);}
}
